        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Peter Thiel, il nuovo mondo degli oligarchi «oltre» la democrazia",
        "testo_it": "Analisi sull'influenza politica di Peter Thiel e sulla visione degli oligarchi tech oltre la democrazia.",
        "priorita": "Media",
        "id_gruppo": 10,
        "link": "https://ilmanifesto.it/peter-thiel-il-nuovo-mondo-degli-oligarchi-oltre-la-democrazia",
        "orario": "00:05 - 15 Marzo",
